import ast
import hashlib
import math
from collections import Counter, defaultdict
from typing import Any, Dict, List, Optional, Set, Tuple

class PatternResonance:
    """
    Detects structural patterns across codebases by measuring phase-alignment similarity
    between abstract syntax trees (ASTs). Identifies recurring motifs, anti-patterns,
    and architectural harmonies.
    """

    def __init__(self, min_similarity: float = 0.7, max_patterns: int = 10):
        """
        Initialize the detector.

        Args:
            min_similarity: Minimum similarity (0.0 to 1.0) for two subtrees to be considered resonant.
            max_patterns: Maximum number of patterns to return.
        """
        self.min_similarity = min_similarity
        self.max_patterns = max_patterns

    def analyze(self, code_snippets: List[str]) -> Dict[str, Any]:
        """
        Analyze a list of code snippets to find structural patterns.

        Args:
            code_snippets: List of Python source code strings.

        Returns:
            A dictionary containing:
                - 'patterns': list of detected patterns with their frequency and representative snippet.
                - 'anti_patterns': list of detected anti-patterns (e.g., deeply nested code).
                - 'harmonies': list of pairs of snippets that are structurally similar.
        """
        if not code_snippets:
            return {'patterns': [], 'anti_patterns': [], 'harmonies': []}

        # Parse all snippets into ASTs
        asts = []
        for snippet in code_snippets:
            try:
                tree = ast.parse(snippet)
                asts.append(tree)
            except SyntaxError:
                # Skip invalid snippets
                continue

        if not asts:
            return {'patterns': [], 'anti_patterns': [], 'harmonies': []}

        # Extract all subtrees (with positions) from each AST
        all_subtrees = []  # list of (tree_index, node, path_hash, size)
        for idx, tree in enumerate(asts):
            for node in ast.walk(tree):
                # Only consider nodes that are statements or expressions (structural)
                if isinstance(node, (ast.stmt, ast.expr)):
                    path_hash = self._structural_hash(node)
                    size = self._subtree_size(node)
                    all_subtrees.append((idx, node, path_hash, size))

        # Group subtrees by structural hash (exact structural match)
        hash_groups = defaultdict(list)
        for idx, node, path_hash, size in all_subtrees:
            hash_groups[path_hash].append((idx, node, size))

        # Find recurring motifs: hashes that appear in multiple snippets or multiple times
        patterns = []
        for path_hash, occurrences in hash_groups.items():
            if len(occurrences) >= 2:
                # Compute frequency as number of occurrences
                freq = len(occurrences)
                # Representative snippet from the first occurrence
                rep_snippet = ast.unparse(occurrences[0][1])
                patterns.append({
                    'hash': path_hash,
                    'frequency': freq,
                    'snippet': rep_snippet,
                    'size': occurrences[0][2]
                })

        # Sort patterns by frequency descending, then size descending
        patterns.sort(key=lambda p: (-p['frequency'], -p['size']))
        patterns = patterns[:self.max_patterns]

        # Detect anti-patterns: deeply nested control flow (e.g., nesting depth > 3)
        anti_patterns = []
        for idx, tree in enumerate(asts):
            for node in ast.walk(tree):
                if isinstance(node, (ast.If, ast.For, ast.While, ast.With)):
                    depth = self._nesting_depth(node)
                    if depth > 3:
                        anti_patterns.append({
                            'type': type(node).__name__,
                            'depth': depth,
                            'snippet': ast.unparse(node)
                        })

        # Find harmonies: pairs of snippets with high phase-alignment similarity
        harmonies = []
        for i in range(len(asts)):
            for j in range(i+1, len(asts)):
                sim = self._phase_alignment_similarity(asts[i], asts[j])
                if sim >= self.min_similarity:
                    harmonies.append({
                        'snippet_indices': (i, j),
                        'similarity': sim
                    })

        return {
            'patterns': patterns,
            'anti_patterns': anti_patterns,
            'harmonies': harmonies
        }

    def _structural_hash(self, node: ast.AST) -> str:
        """
        Compute a hash representing the structural shape of a subtree.
        The hash is based on the sequence of node types and their nesting.
        """
        def shape(n: ast.AST) -> str:
            # For leaf nodes, include the type and maybe constant value type
            if isinstance(n, ast.Constant):
                return f"Constant:{type(n.value).__name__}"
            if isinstance(n, ast.Name):
                return "Name"
            if isinstance(n, ast.Attribute):
                return "Attribute"
            # For other nodes, use the class name
            return type(n).__name__

        # Traverse the subtree in pre-order and build a string
        parts = []
        def visit(n: ast.AST):
            parts.append(shape(n))
            for child in ast.iter_child_nodes(n):
                visit(child)
        visit(node)
        # Hash the string
        return hashlib.sha256('|'.join(parts).encode()).hexdigest()

    def _subtree_size(self, node: ast.AST) -> int:
        """Count the number of nodes in the subtree."""
        return sum(1 for _ in ast.walk(node))

    def _nesting_depth(self, node: ast.AST) -> int:
        """Compute the nesting depth of control flow structures."""
        depth = 0
        current = node
        while current:
            if isinstance(current, (ast.If, ast.For, ast.While, ast.With)):
                depth += 1
            current = getattr(current, 'parent', None)
        return depth

    def _phase_alignment_similarity(self, tree1: ast.AST, tree2: ast.AST) -> float:
        """
        Compute a similarity score between two ASTs based on the distribution of
        structural features (phase alignment).
        """
        # Extract feature vectors: counts of node types and structural hashes
        features1 = self._feature_vector(tree1)
        features2 = self._feature_vector(tree2)

        # Compute cosine similarity between the feature vectors
        common = set(features1.keys()) & set(features2.keys())
        if not common:
            return 0.0

        dot = sum(features1[k] * features2[k] for k in common)
        norm1 = math.sqrt(sum(v*v for v in features1.values()))
        norm2 = math.sqrt(sum(v*v for v in features2.values()))
        if norm1 == 0 or norm2 == 0:
            return 0.0
        return dot / (norm1 * norm2)

    def _feature_vector(self, tree: ast.AST) -> Dict[str, int]:
        """
        Build a feature vector from an AST: counts of node types and structural hashes.
        """
        counter = Counter()
        for node in ast.walk(tree):
            if isinstance(node, (ast.stmt, ast.expr)):
                # Add node type feature
                counter[type(node).__name__] += 1
                # Add structural hash feature (for small subtrees to capture local patterns)
                if self._subtree_size(node) <= 10:
                    h = self._structural_hash(node)
                    counter[f"hash:{h}"] += 1
        return dict(counter)

import math
import random
from dataclasses import dataclass, field
from typing import List, Dict, Optional, Tuple, Callable

@dataclass
class StateOrbital:
    """
    Models system states as phases on a Kuramoto oscillator network.
    Each state is represented by a phase angle; transitions are designed
    to maintain phase coherence across distributed components.
    """
    num_states: int
    coupling: float = 1.0
    natural_frequencies: Optional[List[float]] = None
    phases: List[float] = field(default_factory=list)
    adjacency: List[List[float]] = field(default_factory=list)

    def __post_init__(self):
        if self.num_states <= 0:
            raise ValueError("num_states must be positive")
        if self.coupling < 0:
            raise ValueError("coupling must be non-negative")
        if self.natural_frequencies is None:
            self.natural_frequencies = [0.0] * self.num_states
        elif len(self.natural_frequencies) != self.num_states:
            raise ValueError("natural_frequencies length must match num_states")
        if not self.phases:
            self.phases = [0.0] * self.num_states
        elif len(self.phases) != self.num_states:
            raise ValueError("phases length must match num_states")
        if not self.adjacency:
            # default: all-to-all coupling with weight 1
            self.adjacency = [[1.0 if i != j else 0.0 for j in range(self.num_states)] for i in range(self.num_states)]
        elif len(self.adjacency) != self.num_states:
            raise ValueError("adjacency must be square matrix of size num_states")
        else:
            for row in self.adjacency:
                if len(row) != self.num_states:
                    raise ValueError("adjacency must be square matrix")

    def phase_coherence(self) -> float:
        """Compute the Kuramoto order parameter (0 to 1)."""
        if not self.phases:
            return 0.0
        real = sum(math.cos(p) for p in self.phases)
        imag = sum(math.sin(p) for p in self.phases)
        return math.hypot(real, imag) / len(self.phases)

    def synchronization_trap(self, threshold: float = 0.95) -> bool:
        """
        Detect if the system is in a synchronization trap: high coherence
        but with locked phases that prevent flexible transitions.
        """
        if threshold < 0 or threshold > 1:
            raise ValueError("threshold must be between 0 and 1")
        coherence = self.phase_coherence()
        if coherence < threshold:
            return False
        # Check if phases are too tightly clustered (variance low)
        mean_phase = math.atan2(sum(math.sin(p) for p in self.phases), sum(math.cos(p) for p in self.phases))
        variance = sum((p - mean_phase) ** 2 for p in self.phases) / len(self.phases)
        return variance < 0.1  # heuristic

    def kuramoto_step(self, dt: float = 0.01) -> None:
        """Advance phases using Kuramoto dynamics."""
        if dt <= 0:
            raise ValueError("dt must be positive")
        n = self.num_states
        new_phases = [0.0] * n
        for i in range(n):
            coupling_sum = 0.0
            for j in range(n):
                if i != j:
                    coupling_sum += self.adjacency[i][j] * math.sin(self.phases[j] - self.phases[i])
            new_phases[i] = self.phases[i] + dt * (self.natural_frequencies[i] + self.coupling * coupling_sum)
        self.phases = new_phases

    def design_transition(self, target_state: int, duration: float = 1.0, steps: int = 100) -> List[float]:
        """
        Design a sequence of phase adjustments to transition to a target state
        while maintaining coherence. Returns a list of phase offsets to apply.
        """
        if target_state < 0 or target_state >= self.num_states:
            raise ValueError("target_state out of range")
        if duration <= 0 or steps <= 0:
            raise ValueError("duration and steps must be positive")
        # Simple approach: linear interpolation from current phase to target phase
        # with a correction to keep coherence high.
        current_phase = self.phases[target_state]
        target_phase = self._desired_phase(target_state)
        delta = target_phase - current_phase
        # Normalize delta to [-pi, pi]
        delta = (delta + math.pi) % (2 * math.pi) - math.pi
        offsets = []
        for step in range(1, steps + 1):
            fraction = step / steps
            offsets.append(delta * fraction)
        return offsets

    def _desired_phase(self, state: int) -> float:
        """Placeholder for desired phase; could be based on state index."""
        return 2 * math.pi * state / self.num_states

    def apply_transition(self, offsets: List[float], dt: float = 0.01) -> None:
        """Apply a sequence of phase offsets to the target state."""
        if not offsets:
            return
        if dt <= 0:
            raise ValueError("dt must be positive")
        # Apply offsets to the first state? In a real system, we'd specify which state.
        # Here we assume offsets are for the first state for simplicity.
        for offset in offsets:
            self.phases[0] += offset
            self.kuramoto_step(dt)

    def simulate(self, steps: int = 100, dt: float = 0.01) -> List[float]:
        """Run Kuramoto dynamics for given steps and return coherence history."""
        if steps < 0:
            raise ValueError("steps must be non-negative")
        history = []
        for _ in range(steps):
            self.kuramoto_step(dt)
            history.append(self.phase_coherence())
        return history

    def detect_traps(self, threshold: float = 0.95) -> List[int]:
        """Return indices of states that are in a synchronization trap."""
        traps = []
        for i in range(self.num_states):
            # Check if state i is too close to the mean phase
            mean_phase = math.atan2(sum(math.sin(p) for p in self.phases), sum(math.cos(p) for p in self.phases))
            diff = abs(self.phases[i] - mean_phase)
            diff = min(diff, 2 * math.pi - diff)
            if diff < 0.1 and self.phase_coherence() > threshold:
                traps.append(i)
        return traps

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple


@dataclass(frozen=True)
class Capability:
    """Represents a provider capability with a name and a set of parameters."""
    name: str
    parameters: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.name:
            raise ValueError("Capability name cannot be empty")
        if not all(isinstance(p, str) and p for p in self.parameters):
            raise ValueError("All parameters must be non-empty strings")


@dataclass(frozen=True)
class Expectation:
    """Represents a consumer expectation with a name and a set of parameters."""
    name: str
    parameters: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.name:
            raise ValueError("Expectation name cannot be empty")
        if not all(isinstance(p, str) and p for p in self.parameters):
            raise ValueError("All parameters must be non-empty strings")


@dataclass
class Resonance:
    """Represents a resonant match between an expectation and a capability."""
    expectation: Expectation
    capability: Capability
    frequency: float
    phase_shift: float
    impedance: float

    def __repr__(self) -> str:
        return (
            f"Resonance(expectation={self.expectation.name!r}, "
            f"capability={self.capability.name!r}, frequency={self.frequency:.3f}, "
            f"phase_shift={self.phase_shift:.3f}, impedance={self.impedance:.3f})"
        )


class ContractResonance:
    """
    Finds resonant frequencies between consumer expectations and provider capabilities.

    The resonance is computed based on parameter overlap and name similarity.
    Impedance matching is determined by the difference in parameter counts.
    """

    def __init__(self, provider_capabilities: Optional[List[Capability]] = None) -> None:
        """
        Initialize with an optional list of provider capabilities.

        Args:
            provider_capabilities: Initial capabilities. If None, empty list.
        """
        self._capabilities: List[Capability] = []
        if provider_capabilities:
            for cap in provider_capabilities:
                self.add_capability(cap)

    def add_capability(self, capability: Capability) -> None:
        """Add a provider capability."""
        if not isinstance(capability, Capability):
            raise TypeError("capability must be a Capability instance")
        self._capabilities.append(capability)

    def remove_capability(self, capability: Capability) -> None:
        """Remove a provider capability if present."""
        try:
            self._capabilities.remove(capability)
        except ValueError:
            raise ValueError(f"Capability {capability.name!r} not found")

    def find_resonances(self, expectations: List[Expectation]) -> List[Resonance]:
        """
        Find all resonances between given expectations and provider capabilities.

        Args:
            expectations: List of consumer expectations.

        Returns:
            List of Resonance objects, sorted by frequency descending.

        Raises:
            TypeError: If expectations is not a list of Expectation.
        """
        if not isinstance(expectations, list) or not all(isinstance(e, Expectation) for e in expectations):
            raise TypeError("expectations must be a list of Expectation instances")

        resonances: List[Resonance] = []
        for exp in expectations:
            for cap in self._capabilities:
                freq, phase = self._compute_resonance(exp, cap)
                if freq > 0.0:
                    impedance = self._compute_impedance(exp, cap)
                    resonances.append(Resonance(exp, cap, freq, phase, impedance))

        # Sort by frequency descending, then by impedance ascending
        resonances.sort(key=lambda r: (-r.frequency, r.impedance))
        return resonances

    def design_contract(self, expectations: List[Expectation]) -> Dict[str, Any]:
        """
        Design an API contract by matching each expectation to the best capability.

        Returns a dictionary with:
            - 'matches': list of dicts with expectation, capability, frequency, impedance
            - 'unmatched_expectations': list of expectation names not matched
            - 'unused_capabilities': list of capability names not used

        Args:
            expectations: List of consumer expectations.

        Returns:
            Contract design dictionary.
        """
        resonances = self.find_resonances(expectations)
        used_capabilities = set()
        matched_expectations = set()
        matches = []

        for res in resonances:
            if res.expectation.name in matched_expectations:
                continue
            if res.capability.name in used_capabilities:
                continue
            # Accept match if impedance is within threshold (e.g., <= 2)
            if res.impedance <= 2.0:
                matches.append({
                    'expectation': res.expectation.name,
                    'capability': res.capability.name,
                    'frequency': res.frequency,
                    'impedance': res.impedance,
                })
                matched_expectations.add(res.expectation.name)
                used_capabilities.add(res.capability.name)

        unmatched = [e.name for e in expectations if e.name not in matched_expectations]
        unused = [c.name for c in self._capabilities if c.name not in used_capabilities]

        return {
            'matches': matches,
            'unmatched_expectations': unmatched,
            'unused_capabilities': unused,
        }

    def _compute_resonance(self, exp: Expectation, cap: Capability) -> Tuple[float, float]:
        """
        Compute resonance frequency and phase shift between expectation and capability.

        The frequency is based on name similarity and parameter overlap.
        Phase shift is based on parameter order differences.

        Returns:
            (frequency, phase_shift). Frequency is 0 if no overlap.
        """
        # Name similarity using Jaccard-like on character bigrams
        name_sim = self._jaccard_bigrams(exp.name.lower(), cap.name.lower())

        # Parameter overlap
        exp_params = set(exp.parameters)
        cap_params = set(cap.parameters)
        if exp_params or cap_params:
            overlap = len(exp_params & cap_params) / max(len(exp_params | cap_params), 1)
        else:
            overlap = 1.0  # both empty

        # Frequency: combine name similarity and parameter overlap
        # Use a weighted harmonic mean to emphasize overlap
        if name_sim + overlap == 0:
            return 0.0, 0.0
        freq = 2.0 * name_sim * overlap / (name_sim + overlap + 1e-9)

        # Phase shift: based on parameter order difference
        phase = self._compute_phase_shift(exp.parameters, cap.parameters)

        return freq, phase

    def _compute_phase_shift(self, exp_params: Tuple[str, ...], cap_params: Tuple[str, ...]) -> float:
        """Compute phase shift based on parameter order differences."""
        if not exp_params or not cap_params:
            return 0.0
        # Use normalized Levenshtein distance on parameter sequences
        max_len = max(len(exp_params), len(cap_params))
        if max_len == 0:
            return 0.0
        dist = self._levenshtein(exp_params, cap_params)
        return dist / max_len

    def _compute_impedance(self, exp: Expectation, cap: Capability) -> float:
        """Compute impedance mismatch based on parameter count difference."""
        diff = abs(len(exp.parameters) - len(cap.parameters))
        # Impedance grows with difference, but also penalize missing required params
        missing = len(set(exp.parameters) - set(cap.parameters))
        return float(diff + missing)

    @staticmethod
    def _jaccard_bigrams(s1: str, s2: str) -> float:
        """Compute Jaccard similarity between character bigrams of two strings."""
        if s1 == s2:
            return 1.0
        bigrams1 = {s1[i:i+2] for i in range(len(s1)-1)} if len(s1) > 1 else {s1}
        bigrams2 = {s2[i:i+2] for i in range(len(s2)-1)} if len(s2) > 1 else {s2}
        if not bigrams1 or not bigrams2:
            return 0.0
        intersection = len(bigrams1 & bigrams2)
        union = len(bigrams1 | bigrams2)
        return intersection / union if union else 0.0

    @staticmethod
    def _levenshtein(a: Tuple[str, ...], b: Tuple[str, ...]) -> int:
        """Compute Levenshtein distance between two sequences of strings."""
        m, n = len(a), len(b)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                cost = 0 if a[i-1] == b[j-1] else 1
                dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + cost)
        return dp[m][n]

from typing import Dict, List, Tuple, Set, Optional, Any, Callable
from collections import defaultdict, deque
import math

class DataFlowTopology:
    """
    Analyzes a directed graph representing data flow between components.
    Each edge has a flow rate (positive number).
    Detects:
    - Vortices: strongly connected components with cycles (circular dependencies).
    - Sources: nodes with no incoming edges (unbounded growth potential).
    - Sinks: nodes with no outgoing edges (data loss potential).
    Also computes a topological ordering if acyclic.
    """

    def __init__(self, adjacency: Dict[str, Dict[str, float]]):
        """
        :param adjacency: mapping from node to dict of {neighbor: flow_rate}.
                         Flow rates must be positive numbers.
        """
        self.adjacency = {k: dict(v) for k, v in adjacency.items()}
        self.nodes: Set[str] = set(self.adjacency.keys())
        # Ensure all targets are also nodes (with empty dict if missing)
        for targets in self.adjacency.values():
            for t in targets:
                if t not in self.nodes:
                    self.nodes.add(t)
                    self.adjacency[t] = {}
        self._validate()

    def _validate(self) -> None:
        """Validate that all flow rates are positive numbers."""
        for src, targets in self.adjacency.items():
            for tgt, rate in targets.items():
                if not isinstance(rate, (int, float)) or isinstance(rate, bool):
                    raise TypeError(f"Flow rate from {src} to {tgt} must be a number, got {type(rate).__name__}")
                if rate <= 0:
                    raise ValueError(f"Flow rate from {src} to {tgt} must be positive, got {rate}")

    def get_sources(self) -> List[str]:
        """Nodes with no incoming edges."""
        incoming = {n: 0 for n in self.nodes}
        for targets in self.adjacency.values():
            for t in targets:
                incoming[t] += 1
        return sorted([n for n in self.nodes if incoming[n] == 0])

    def get_sinks(self) -> List[str]:
        """Nodes with no outgoing edges."""
        return sorted([n for n in self.nodes if not self.adjacency[n]])

    def get_vortices(self) -> List[List[str]]:
        """
        Returns list of strongly connected components (SCCs) that contain at least one cycle.
        Each SCC is a list of node names sorted.
        """
        # Tarjan's algorithm for SCC
        index = 0
        indices: Dict[str, int] = {}
        lowlink: Dict[str, int] = {}
        on_stack: Set[str] = set()
        stack: List[str] = []
        sccs: List[List[str]] = []

        def strongconnect(v: str) -> None:
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack.add(v)

            for w in self.adjacency[v]:
                if w not in indices:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])

            if lowlink[v] == indices[v]:
                scc: List[str] = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    scc.append(w)
                    if w == v:
                        break
                sccs.append(scc)

        for v in self.nodes:
            if v not in indices:
                strongconnect(v)

        # A vortex is an SCC with more than one node, or a self-loop
        vortices = []
        for scc in sccs:
            if len(scc) > 1:
                vortices.append(sorted(scc))
            elif len(scc) == 1:
                node = scc[0]
                if node in self.adjacency[node]:
                    vortices.append([node])
        return vortices

    def has_cycle(self) -> bool:
        """Returns True if the graph has at least one cycle."""
        return len(self.get_vortices()) > 0

    def topological_sort(self) -> List[str]:
        """
        Returns a topological ordering of nodes if the graph is acyclic.
        Raises ValueError if a cycle exists.
        """
        if self.has_cycle():
            raise ValueError("Cannot topologically sort a graph with cycles")
        in_degree = {n: 0 for n in self.nodes}
        for targets in self.adjacency.values():
            for t in targets:
                in_degree[t] += 1
        queue = deque([n for n in self.nodes if in_degree[n] == 0])
        order = []
        while queue:
            node = queue.popleft()
            order.append(node)
            for neighbor in self.adjacency[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)
        if len(order) != len(self.nodes):
            raise ValueError("Graph has a cycle")
        return order

    def analyze(self) -> Dict[str, Any]:
        """
        Returns a summary dictionary with sources, sinks, vortices, and acyclic status.
        """
        return {
            "sources": self.get_sources(),
            "sinks": self.get_sinks(),
            "vortices": self.get_vortices(),
            "has_cycle": self.has_cycle(),
            "topological_order": self.topological_sort() if not self.has_cycle() else None
        }

    def flow_balance(self) -> Dict[str, float]:
        """
        Computes net flow for each node: total outgoing - total incoming.
        Positive indicates source-like, negative sink-like.
        """
        balance = {n: 0.0 for n in self.nodes}
        for src, targets in self.adjacency.items():
            for tgt, rate in targets.items():
                balance[src] += rate
                balance[tgt] -= rate
        return balance

    def divergence(self) -> Dict[str, float]:
        """Alias for flow_balance."""
        return self.flow_balance()

