class VersionState(Enum):
    STABLE = "stable"
    UNSTABLE = "unstable"
    UNKNOWN = "unknown"

@dataclass
class Version:
    id: str
    state: VersionState = VersionState.UNKNOWN
    stability_score: float = 0.0  # higher is more stable

@dataclass
class RollbackAttractor:
    versions: List[Version] = field(default_factory=list)
    current_version: Optional[str] = None
    history: List[str] = field(default_factory=list)
    attractor_strength: float = 0.8
    damping: float = 0.1
    max_iterations: int = 100

    def __post_init__(self) -> None:
        if not 0.0 <= self.attractor_strength <= 1.0:
            raise ValueError("attractor_strength must be between 0 and 1")
        if self.damping < 0:
            raise ValueError("damping must be non-negative")
        if self.max_iterations <= 0:
            raise ValueError("max_iterations must be positive")
        self._version_map: Dict[str, Version] = {v.id: v for v in self.versions}
        if self.current_version and self.current_version not in self._version_map:
            raise ValueError("current_version not in versions")

    def add_version(self, version: Version) -> None:
        if version.id in self._version_map:
            raise ValueError(f"Version {version.id} already exists")
        self.versions.append(version)
        self._version_map[version.id] = version

    def set_current(self, version_id: str) -> None:
        if version_id not in self._version_map:
            raise ValueError(f"Version {version_id} not found")
        self.current_version = version_id
        self.history.append(version_id)

    def mark_failed(self, version_id: str) -> None:
        if version_id not in self._version_map:
            raise ValueError(f"Version {version_id} not found")
        self._version_map[version_id].state = VersionState.UNSTABLE
        self._version_map[version_id].stability_score = 0.0

    def mark_stable(self, version_id: str, score: float = 1.0) -> None:
        if version_id not in self._version_map:
            raise ValueError(f"Version {version_id} not found")
        if not 0.0 <= score <= 1.0:
            raise ValueError("score must be between 0 and 1")
        self._version_map[version_id].state = VersionState.STABLE
        self._version_map[version_id].stability_score = score

    def _attraction_force(self, candidate: Version, target: Version) -> float:
        """Compute attraction force from target to candidate."""
        if target.state == VersionState.STABLE:
            return self.attractor_strength * target.stability_score
        elif target.state == VersionState.UNSTABLE:
            return -self.attractor_strength * (1 - target.stability_score)
        else:
            return 0.0

    def _convergence_score(self, candidate: Version) -> float:
        """Compute a score indicating how much candidate is attracted to stable states."""
        if not self.versions:
            return 0.0
        total = 0.0
        for target in self.versions:
            if target.id == candidate.id:
                continue
            total += self._attraction_force(candidate, target)
        # Normalize by number of other versions
        return total / max(1, len(self.versions) - 1)

    def _simulate_dynamics(self, candidate: Version) -> float:
        """Simulate the attractor dynamics for a candidate version.
        Returns a stability score after convergence."""
        score = candidate.stability_score
        for _ in range(self.max_iterations):
            attraction = self._convergence_score(candidate)
            # Update score using a simple dynamical system: score += attraction - damping * (score - 0.5)
            new_score = score + attraction - self.damping * (score - 0.5)
            # Clamp to [0,1]
            new_score = max(0.0, min(1.0, new_score))
            if abs(new_score - score) < 1e-6:
                score = new_score
                break
            score = new_score
        return score

    def select_rollback_target(self) -> Optional[str]:
        """Select the best rollback target based on attractor dynamics.
        Returns the version ID that is most stable and converges well."""
        if not self.versions:
            return None
        if self.current_version is None:
            # No current version, pick the most stable
            best = max(self.versions, key=lambda v: v.stability_score)
            return best.id

        # Exclude current version if it's unstable
        candidates = [v for v in self.versions if v.id != self.current_version]
        if not candidates:
            return None

        best_candidate = None
        best_score = -math.inf
        for candidate in candidates:
            # Skip unstable versions unless no stable ones
            if candidate.state == VersionState.UNSTABLE:
                continue
            sim_score = self._simulate_dynamics(candidate)
            # Combine simulated score with actual stability score
            combined = 0.7 * sim_score + 0.3 * candidate.stability_score
            if combined > best_score:
                best_score = combined
                best_candidate = candidate

        # If all candidates are unstable, fall back to the one with highest stability_score
        if best_candidate is None:
            best_candidate = max(candidates, key=lambda v: v.stability_score)
        return best_candidate.id

    def rollback(self) -> Optional[str]:
        """Perform a rollback to the selected target version.
        Updates current_version and history."""
        target = self.select_rollback_target()
        if target is None:
            return None
        self.current_version = target
        self.history.append(target)
        return target

    def get_history(self) -> List[str]:
        return list(self.history)

