from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple, TypeVar, Generic

T = TypeVar('T')

@dataclass
class ClientUsage:
    """Represents a client's usage pattern: which methods it calls."""
    client_id: str
    methods: Set[str]

@dataclass
class Interface:
    """Represents an interface with a set of methods."""
    name: str
    methods: Set[str]

@dataclass
class SegregationResult:
    """Result of interface segregation."""
    interfaces: List[Interface]
    assignments: Dict[str, str]  # client_id -> interface_name
    satisfaction: float  # 0.0 to 1.0
    surface_area: int  # total number of methods across all interfaces

class InterfaceSegregationField:
    """
    Segregates interfaces based on client usage patterns using a field-line clustering approach.

    The algorithm simulates electromagnetic-like attraction: each client exerts a 'force' on
    methods it uses, pulling them together into clusters. Methods that are frequently used
    together form clusters, which become segregated interfaces. The process minimizes the
    total number of methods exposed (surface area) while maximizing the proportion of client
    needs satisfied (each client gets an interface containing all methods it uses).
    """

    def __init__(self, clients: Sequence[ClientUsage], min_clients_per_interface: int = 1):
        """
        Args:
            clients: List of client usage patterns.
            min_clients_per_interface: Minimum number of clients that must use a method for it to be included in an interface.
        """
        if min_clients_per_interface < 1:
            raise ValueError("min_clients_per_interface must be at least 1")
        self.clients = list(clients)
        self.min_clients = min_clients_per_interface
        self._validate()

    def _validate(self) -> None:
        """Ensure clients have unique IDs and non-empty method sets."""
        ids = [c.client_id for c in self.clients]
        if len(ids) != len(set(ids)):
            raise ValueError("Client IDs must be unique")
        for c in self.clients:
            if not c.methods:
                raise ValueError(f"Client {c.client_id} has no methods")

    def segregate(self) -> SegregationResult:
        """
        Perform interface segregation.

        Returns:
            SegregationResult containing the generated interfaces, client assignments,
            satisfaction score, and total surface area.
        """
        # Step 1: Build method usage frequency across all clients
        method_freq: Dict[str, int] = {}
        for c in self.clients:
            for m in c.methods:
                method_freq[m] = method_freq.get(m, 0) + 1

        # Filter methods that are used by at least min_clients clients
        relevant_methods = {m for m, freq in method_freq.items() if freq >= self.min_clients}

        # Step 2: Build co-occurrence matrix (how often two methods appear together)
        # We'll use a simple similarity: Jaccard index between client sets.
        method_to_clients: Dict[str, Set[str]] = {m: set() for m in relevant_methods}
        for c in self.clients:
            for m in c.methods:
                if m in relevant_methods:
                    method_to_clients[m].add(c.client_id)

        # Step 3: Cluster methods using a greedy agglomerative approach based on Jaccard similarity.
        # This simulates field lines pulling methods together.
        clusters: List[Set[str]] = [{m} for m in relevant_methods]

        # While there are clusters, merge the pair with highest similarity.
        while len(clusters) > 1:
            best_pair: Optional[Tuple[int, int]] = None
            best_sim = -1.0
            for i in range(len(clusters)):
                for j in range(i+1, len(clusters)):
                    sim = self._jaccard(clusters[i], clusters[j], method_to_clients)
                    if sim > best_sim:
                        best_sim = sim
                        best_pair = (i, j)
            if best_pair is None or best_sim <= 0.0:
                break
            i, j = best_pair
            merged = clusters[i] | clusters[j]
            # Remove the two and add merged
            new_clusters = [clusters[k] for k in range(len(clusters)) if k != i and k != j]
            new_clusters.append(merged)
            clusters = new_clusters

        # Step 4: Create interfaces from clusters. Each cluster becomes an interface.
        interfaces: List[Interface] = []
        for idx, cluster in enumerate(clusters):
            if cluster:  # non-empty
                interfaces.append(Interface(name=f"I{idx+1}", methods=cluster))

        # Step 5: Assign each client to the interface that contains all its methods.
        # If no single interface contains all, assign to the one with maximum overlap.
        assignments: Dict[str, str] = {}
        satisfied_count = 0
        for c in self.clients:
            best_interface: Optional[Interface] = None
            best_overlap = -1
            for iface in interfaces:
                overlap = len(c.methods & iface.methods)
                if overlap > best_overlap:
                    best_overlap = overlap
                    best_interface = iface
            if best_interface is None:
                # No interface at all (shouldn't happen if there are methods)
                assignments[c.client_id] = ""
                continue
            assignments[c.client_id] = best_interface.name
            if c.methods.issubset(best_interface.methods):
                satisfied_count += 1

        # Step 6: Compute metrics
        total_methods = sum(len(i.methods) for i in interfaces)
        satisfaction = satisfied_count / len(self.clients) if self.clients else 0.0

        return SegregationResult(
            interfaces=interfaces,
            assignments=assignments,
            satisfaction=satisfaction,
            surface_area=total_methods
        )

    @staticmethod
    def _jaccard(set1: Set[str], set2: Set[str], method_to_clients: Dict[str, Set[str]]) -> float:
        """Compute Jaccard similarity between two method sets based on client overlap."""
        clients1 = set()
        clients2 = set()
        for m in set1:
            clients1 |= method_to_clients.get(m, set())
        for m in set2:
            clients2 |= method_to_clients.get(m, set())
        union = clients1 | clients2
        if not union:
            return 0.0
        intersection = clients1 & clients2
        return len(intersection) / len(union)

from typing import Any, Callable, Dict, Generic, List, Optional, TypeVar, Union
from collections import defaultdict
import inspect
import warnings

T = TypeVar('T')

class ResonanceError(AssertionError):
    """Raised when a mock's behavior is out of phase with expectations."""
    pass

class MockResonance(Generic[T]):
    """
    A test double that mimics the behavior of a real dependency with phase consistency.

    The mock records call patterns and can be configured to return values or raise
    exceptions based on the call signature. It also tracks call order and frequency
    to ensure that the mock's behavior is consistent with the expected resonance.
    """

    def __init__(self, spec: Optional[Any] = None) -> None:
        """
        Initialize the mock.

        Args:
            spec: An optional object whose attributes and methods will be mimicked.
        """
        self._spec = spec
        self._methods: Dict[str, Callable[..., Any]] = {}
        self._calls: List[Dict[str, Any]] = []
        self._expected_calls: List[Dict[str, Any]] = []
        self._return_values: Dict[str, List[Any]] = defaultdict(list)
        self._side_effects: Dict[str, List[Callable[..., Any]]] = defaultdict(list)
        self._exceptions: Dict[str, List[Exception]] = defaultdict(list)
        self._call_counts: Dict[str, int] = defaultdict(int)
        self._phase_enabled: bool = True

        if spec is not None:
            self._configure_from_spec(spec)

    def _configure_from_spec(self, spec: Any) -> None:
        """
        Copy methods from the spec object to the mock.
        """
        for name, method in inspect.getmembers(spec, inspect.ismethod):
            if not name.startswith('_'):
                self._methods[name] = self._create_method(name)

    def _create_method(self, name: str) -> Callable[..., Any]:
        """
        Create a method that records calls and returns configured values.
        """
        def method(*args: Any, **kwargs: Any) -> Any:
            return self._handle_call(name, args, kwargs)
        method.__name__ = name
        return method

    def _handle_call(self, name: str, args: tuple, kwargs: dict) -> Any:
        """
        Record the call and determine the return value.
        """
        call_record = {
            'name': name,
            'args': args,
            'kwargs': kwargs,
            'call_index': len(self._calls)
        }
        self._calls.append(call_record)
        self._call_counts[name] += 1

        # Check phase consistency if enabled
        if self._phase_enabled:
            self._check_phase(name, args, kwargs)

        # Determine return value or side effect
        if name in self._exceptions and self._exceptions[name]:
            exc = self._exceptions[name].pop(0)
            raise exc
        if name in self._side_effects and self._side_effects[name]:
            effect = self._side_effects[name].pop(0)
            return effect(*args, **kwargs)
        if name in self._return_values and self._return_values[name]:
            return self._return_values[name].pop(0)
        # Default: return None or a child mock if spec has a method
        if self._spec is not None and hasattr(self._spec, name):
            return None
        return None

    def _check_phase(self, name: str, args: tuple, kwargs: dict) -> None:
        """
        Verify that the call matches the expected pattern (phase).
        """
        if self._expected_calls:
            expected = self._expected_calls[0]
            if expected['name'] != name:
                raise ResonanceError(
                    f"Phase mismatch: expected call to '{expected['name']}' but got '{name}'"
                )
            # Compare args and kwargs loosely (exact match for now)
            if expected['args'] != args or expected['kwargs'] != kwargs:
                raise ResonanceError(
                    f"Phase mismatch for '{name}': expected args {expected['args']} kwargs {expected['kwargs']} but got args {args} kwargs {kwargs}"
                )
            self._expected_calls.pop(0)

    def __getattr__(self, name: str) -> Any:
        """
        Dynamically create methods for attributes not explicitly defined.
        """
        if name.startswith('_'):
            raise AttributeError(f"{type(self).__name__} has no attribute {name!r}")
        if name not in self._methods:
            self._methods[name] = self._create_method(name)
        return self._methods[name]

    def __setattr__(self, name: str, value: Any) -> None:
        """
        Allow setting attributes, but intercept method configuration.
        """
        if name.startswith('_'):
            super().__setattr__(name, value)
        else:
            # If setting a callable, treat as a method replacement
            if callable(value):
                self._methods[name] = value
            else:
                super().__setattr__(name, value)

    def configure(self, name: str, return_value: Any = None, side_effect: Optional[Callable[..., Any]] = None, exception: Optional[Exception] = None) -> None:
        """
        Configure the behavior of a method.

        Args:
            name: Method name.
            return_value: Value to return when called.
            side_effect: Function to call; its return value is returned.
            exception: Exception to raise when called.
        """
        if exception is not None:
            self._exceptions[name].append(exception)
        elif side_effect is not None:
            self._side_effects[name].append(side_effect)
        else:
            self._return_values[name].append(return_value)

    def expect_call(self, name: str, *args: Any, **kwargs: Any) -> None:
        """
        Expect a call with specific arguments in the future.
        """
        self._expected_calls.append({'name': name, 'args': args, 'kwargs': kwargs})

    def assert_called(self, name: str, times: Optional[int] = None) -> None:
        """
        Assert that a method was called a certain number of times.
        """
        count = self._call_counts.get(name, 0)
        if times is not None and count != times:
            raise AssertionError(f"Expected {name} to be called {times} times, but was called {count} times")
        if times is None and count == 0:
            raise AssertionError(f"Expected {name} to have been called, but it wasn't")

    def assert_phase_consistent(self) -> None:
        """
        Assert that all expected calls have been made.
        """
        if self._expected_calls:
            remaining = [c['name'] for c in self._expected_calls]
            raise ResonanceError(f"Expected calls not made: {remaining}")

    def enable_phase_checking(self, enabled: bool = True) -> None:
        """
        Enable or disable phase checking.
        """
        self._phase_enabled = enabled

    def reset(self) -> None:
        """
        Reset all recorded calls and configurations.
        """
