from __future__ import annotations

import math
import random
from dataclasses import dataclass, field
from typing import List, Optional, Sequence, Tuple


@dataclass
class OrbitalConsensus:
    """
    Distributed consensus via phase synchronization.

    Agents are represented as oscillators with phases. They interact through
    Kuramoto coupling, adjusting phases based on neighbors. The consensus
    value is derived from the average phase after convergence.

    The algorithm is fully decentralized: no leader, no central authority.
    Each agent only communicates with its neighbors.

    Attributes:
        num_agents: Number of agents in the system.
        coupling: Coupling strength K (positive).
        dt: Time step for numerical integration.
        max_steps: Maximum number of iterations.
        convergence_threshold: Phase difference threshold for convergence.
        phases: Current phases of agents (radians).
        adjacency: Adjacency matrix (list of lists) indicating neighbors.
    """

    num_agents: int
    coupling: float = 1.0
    dt: float = 0.01
    max_steps: int = 1000
    convergence_threshold: float = 1e-3
    phases: List[float] = field(default_factory=list)
    adjacency: Optional[List[List[int]]] = None

    def __post_init__(self) -> None:
        if self.num_agents <= 0:
            raise ValueError("num_agents must be positive")
        if self.coupling <= 0:
            raise ValueError("coupling must be positive")
        if self.dt <= 0:
            raise ValueError("dt must be positive")
        if self.max_steps <= 0:
            raise ValueError("max_steps must be positive")
        if self.convergence_threshold <= 0:
            raise ValueError("convergence_threshold must be positive")

        # Initialize phases randomly in [0, 2*pi)
        if not self.phases:
            self.phases = [random.uniform(0, 2 * math.pi) for _ in range(self.num_agents)]
        elif len(self.phases) != self.num_agents:
            raise ValueError("phases length must match num_agents")

        # Default adjacency: complete graph (all-to-all)
        if self.adjacency is None:
            self.adjacency = [list(range(self.num_agents)) for _ in range(self.num_agents)]
        else:
            if len(self.adjacency) != self.num_agents:
                raise ValueError("adjacency must have num_agents rows")
            for i, neighbors in enumerate(self.adjacency):
                if i not in neighbors:
                    # Ensure self-loop for stability (optional but common)
                    self.adjacency[i] = neighbors + [i]

    def step(self) -> None:
        """Perform one synchronous update of all phases using Kuramoto coupling."""
        new_phases = [0.0] * self.num_agents
        for i in range(self.num_agents):
            sum_sin = 0.0
            for j in self.adjacency[i]:
                if j != i:  # exclude self (self-coupling has no effect)
                    sum_sin += math.sin(self.phases[j] - self.phases[i])
            # Kuramoto update: dtheta_i/dt = omega_i + K/N * sum(sin(theta_j - theta_i))
            # We assume zero natural frequency (omega_i = 0) for consensus.
            # Using Euler integration.
            new_phases[i] = self.phases[i] + self.dt * (self.coupling / self.num_agents) * sum_sin
        self.phases = new_phases

    def order_parameter(self) -> float:
        """
        Compute the Kuramoto order parameter r (0 <= r <= 1).
        r = 1 indicates perfect synchronization.
        """
        real = sum(math.cos(p) for p in self.phases) / self.num_agents
        imag = sum(math.sin(p) for p in self.phases) / self.num_agents
        return math.hypot(real, imag)

    def is_converged(self) -> bool:
        """Check if phases are sufficiently close (max pairwise difference < threshold)."""
        if self.num_agents <= 1:
            return True
        # Compute circular mean and check max deviation
        mean_angle = self.mean_phase()
        max_dev = max(abs((p - mean_angle + math.pi) % (2 * math.pi) - math.pi) for p in self.phases)
        return max_dev < self.convergence_threshold

    def mean_phase(self) -> float:
        """Compute the circular mean of phases."""
        real = sum(math.cos(p) for p in self.phases) / self.num_agents
        imag = sum(math.sin(p) for p in self.phases) / self.num_agents
        return math.atan2(imag, real)

    def run(self) -> Tuple[float, int]:
        """
        Run the consensus algorithm until convergence or max_steps.

        Returns:
            (consensus_value, steps_taken) where consensus_value is the mean phase.
        """
        for step in range(self.max_steps):
            if self.is_converged():
                break
            self.step()
        return self.mean_phase(), step + 1

    def get_consensus_value(self) -> float:
        """Return the current consensus value (mean phase)."""
        return self.mean_phase()

    def reset(self, phases: Optional[Sequence[float]] = None) -> None:
        """Reset phases to given values or random."""
        if phases is None:
            self.phases = [random.uniform(0, 2 * math.pi) for _ in range(self.num_agents)]
        else:
            if len(phases) != self.num_agents:
                raise ValueError("phases length must match num_agents")
            self.phases = list(phases)
